 *         return StorageSlot.getAddressSlot(_IMPLEMENTATION_SLOT).value;
 *     }
 *
 *     function _setImplementation(address newImplementation) internal {
 *         require(newImplementation.code.length > 0);
 *         StorageSlot.getAddressSlot(_IMPLEMENTATION_SLOT).value = newImplementation;
 *     }
 * }
 * ```
 *
 * TIP: Consider using this library along with {SlotDerivation}.
 */
library StorageSlot {
    struct AddressSlot {
        address value;
    }

    struct BooleanSlot {
        bool value;
    }

    struct Bytes32Slot {
        bytes32 value;
    }

    struct Uint256Slot {
        uint256 value;
    }

    struct Int256Slot {
        int256 value;
    }

    struct StringSlot {
        string value;
    }

    struct BytesSlot {
        bytes value;
    }

    /**
     * @dev Returns an `AddressSlot` with member `value` located at `slot`.
     */
    function getAddressSlot(bytes32 slot) internal pure returns (AddressSlot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns a `BooleanSlot` with member `value` located at `slot`.
     */
    function getBooleanSlot(bytes32 slot) internal pure returns (BooleanSlot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns a `Bytes32Slot` with member `value` located at `slot`.
     */
    function getBytes32Slot(bytes32 slot) internal pure returns (Bytes32Slot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns a `Uint256Slot` with member `value` located at `slot`.
     */
    function getUint256Slot(bytes32 slot) internal pure returns (Uint256Slot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns a `Int256Slot` with member `value` located at `slot`.
     */
    function getInt256Slot(bytes32 slot) internal pure returns (Int256Slot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns a `StringSlot` with member `value` located at `slot`.
     */
    function getStringSlot(bytes32 slot) internal pure returns (StringSlot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns an `StringSlot` representation of the string storage pointer `store`.
     */
    function getStringSlot(string storage store) internal pure returns (StringSlot storage r) {
        assembly ("memory-safe") {
            r.slot := store.slot
        }
    }

    /**
     * @dev Returns a `BytesSlot` with member `value` located at `slot`.
     */
    function getBytesSlot(bytes32 slot) internal pure returns (BytesSlot storage r) {
        assembly ("memory-safe") {
            r.slot := slot
        }
    }

    /**
     * @dev Returns an `BytesSlot` representation of the bytes storage pointer `store`.
     */
    function getBytesSlot(bytes storage store) internal pure returns (BytesSlot storage r) {
        assembly ("memory-safe") {
            r.slot := store.slot
        }
    }
}

contracts/BaseVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title  BaseVault
 * @notice Settlement layer contract for the "Private Agentic DeFi on Base" stack.
 *         Deployed on Base Sepolia (chain 84532) or Base mainnet (chain 8453).
 *
 * ═══════════════════════════════════════════════════════════════════════
 *  ROLE IN THE THREE-LAYER ARCHITECTURE
 * ═══════════════════════════════════════════════════════════════════════
 *
 *   ┌────────────────────────────────────────────────────┐
 *   │  Layer 1 — USER / SETTLEMENT (BASE SEPOLIA)        │
 *   │                                                    │
 *   │  1. User approves BaseVault to spend their ERC-20  │
 *   │  2. User calls deposit(token, amount, strategyId)  │
 *   │  3. BaseVault locks tokens and emits DepositCreated│
 *   │  4. User can link to a Zama fhEVM strategy         │
 *   │  5. User requests withdrawal → funds locked        │
 *   │  6. Relayer completes withdrawal (TODO)            │
 *   └──────────────────────┬─────────────────────────────┘
 *                          │  DepositCreated event
 *                          │  WithdrawalRequested event
 *                          ▼
 *   ┌────────────────────────────────────────────────────┐
 *   │  Layer 2 — BRIDGE / RELAYER (TODO — off-chain)     │
 *   │                                                    │
 *   │  • Watches Base for DepositCreated events          │
 *   │  • Calls ConfidentialToken.shield() on Zama fhEVM │
 *   │  • Watches Zama for Unshielded events              │
 *   │  • Calls relayerCompleteWithdrawal() on Base       │
 *   │                                                    │
 *   │  Status: NOT IMPLEMENTED. See IRelayer.sol.        │
 *   └──────────────────────┬─────────────────────────────┘
 *                          │
 *                          ▼
 *   ┌────────────────────────────────────────────────────┐
 *   │  Layer 3 — CONFIDENTIAL COMPUTE (ZAMA fhEVM)       │
 *   │                                                    │
 *   │  • ConfidentialToken.shield(amount) → euint64      │
 *   │  • ConfidentialStrategyAgent encrypted evaluation  │
 *   │  • TFHE homomorphic operations                     │
 *   │                                                    │
 *   │  Note: Zama fhEVM does NOT run on Base. It is a    │
 *   │  separate network (chain 9000 or Sepolia).         │
 *   └────────────────────────────────────────────────────┘
 *
 * ═══════════════════════════════════════════════════════════════════════
 *  WHAT THIS CONTRACT DOES
 * ═══════════════════════════════════════════════════════════════════════
 *  • Accepts ERC-20 deposits from users
 *  • Tracks per-user, per-token available and pending balances
 *  • Emits events for the off-chain relayer to consume
 *  • Processes withdrawals once the relayer confirms Zama unshield
 *  • Links user accounts to Zama fhEVM strategy IDs
 *
 * ═══════════════════════════════════════════════════════════════════════
 *  WHAT THIS CONTRACT DOES NOT DO
 * ═══════════════════════════════════════════════════════════════════════
 *  • No FHE / TFHE operations of any kind
 *  • No cross-chain message passing (that is the relayer's responsibility)
 *  • No knowledge of encrypted strategy parameters
 *  • No interaction with Zama's ACL or Gateway contracts
 *
 * ═══════════════════════════════════════════════════════════════════════
 *  WITHDRAWAL STATE MACHINE
 * ═══════════════════════════════════════════════════════════════════════
 *  available balance
 *      │
 *      │  requestWithdrawal()
 *      ▼
 *  pending withdrawal
 *      │                   │
 *      │  relayerComplete  │  cancelPendingWithdrawal()
 *      ▼                   ▼
 *  released to user     back to available balance
 *
 *  Emergency path (any user, for their own available balance — testnet/dev):
 *      emergencyWithdraw() — bypasses relayer, transfers directly to msg.sender
 */

import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract BaseVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── State ─────────────────────────────────────────────────────────────────

    /**
     * @notice Address of the authorized relayer that can complete withdrawals.
     *
     * TODO: Set this to the deployed relayer contract address once the
     *       cross-chain bridge is implemented.
     *       For now, the owner acts as the relayer during development.
     */
    address public relayer;

    /**
     * @notice Available (deposited, not pending withdrawal) balance per user per token.
     * key: user address → token address → amount
     */
    mapping(address => mapping(address => uint256)) private _available;

    /**
     * @notice Funds locked awaiting relayer confirmation of Zama unshield.
     * key: user address → token address → amount
     */
    mapping(address => mapping(address => uint256)) private _pending;

    /**
     * @notice The Zama fhEVM strategy ID each user has linked.
     * 0 means no strategy linked.
     * This is an opaque identifier — BaseVault does not validate it.
     * The relayer uses it to know which strategy to interact with on Zama.
     */
    mapping(address => uint256) private _linkedStrategy;

    // ── Events ────────────────────────────────────────────────────────────────

    /**
     * @notice Emitted when a user deposits tokens into the vault.
     *
     * @dev The off-chain relayer MUST listen for this event and call
     *      ConfidentialToken.shield(amount) on Zama fhEVM.
     *      Until the relayer is implemented, funds remain in the vault
     *      but are NOT shielded on Zama.
     *
     * @param user       The depositing user
     * @param token      ERC-20 token address on Base
     * @param amount     Amount deposited (in token's smallest unit)
     * @param strategyId Linked Zama fhEVM strategy (0 if none)
     */
    event DepositCreated(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint256 strategyId
    );

    /**
     * @notice Emitted when a user requests withdrawal from the vault.
     *
     * @dev The relayer MUST listen for this event and initiate
     *      ConfidentialToken.requestUnshield() on Zama fhEVM.
     *      Funds are locked (moved to _pending) until the relayer
     *      calls relayerCompleteWithdrawal() or the user cancels.
     */
    event WithdrawalRequested(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    /**
     * @notice Emitted when the relayer confirms withdrawal completion.
     * @dev    At this point the ERC-20 tokens are transferred to the user.
     */
    event WithdrawalCompleted(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    /**
     * @notice Emitted when a user cancels a pending withdrawal.
     */
    event WithdrawalCancelled(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    /**
     * @notice Emitted when a user links their account to a Zama fhEVM strategy.
     *
     * @dev The relayer uses strategyId to find the correct encrypted strategy
     *      on the Zama fhEVM network when bridging deposits.
     */
    event StrategyLinked(address indexed user, uint256 strategyId);

    /**
     * @notice Emitted when the owner updates the relayer address.
     */
    event RelayerSet(address indexed relayer);

    // ── Modifiers ─────────────────────────────────────────────────────────────

    /**
     * @dev Security fix (SECURITY.md finding 1.4):
     *      Owner fallback removed. Only the designated `relayer` address may
     *      call relayerCompleteWithdrawal(). In production the relayer address
     *      should be a bridge contract with on-chain proof verification, not an EOA.
     *
     *      To perform admin withdrawals during development, set the relayer to
     *      the deployer address via setRelayer() before deployment.
     */
    modifier onlyRelayer() {
        require(
            msg.sender == relayer,
            "BaseVault: caller is not the relayer"
        );
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────

    /**
     * @param _owner   Protocol owner (can set relayer, execute emergency withdraw)
     * @param _relayer Initial relayer address (use owner address until bridge deployed)
     */
    constructor(address _owner, address _relayer) Ownable(_owner) {
        require(_owner != address(0), "BaseVault: zero owner");
        // Relayer may be address(0) at deploy time (set later via setRelayer)
        relayer = _relayer;
        emit RelayerSet(_relayer);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    /**
     * @notice Set the relayer address.
     *
     * @dev TODO: Set to the deployed cross-chain bridge/relayer contract once
     *      the LayerZero / Hyperlane / custom relayer is implemented.
     *
     * @param _relayer New relayer address
     */
    function setRelayer(address _relayer) external onlyOwner {
        relayer = _relayer;
        emit RelayerSet(_relayer);
    }

    // ── Deposit ───────────────────────────────────────────────────────────────

    /**
     * @notice Deposit ERC-20 tokens into the vault.
     *
     * @dev Caller must have called token.approve(address(this), amount) first.
     *
     *      The DepositCreated event signals the off-chain relayer to call
     *      ConfidentialToken.shield(amount) on Zama fhEVM.
     *
     *      Until the relayer bridge is live, funds are safely held here
     *      and can be withdrawn at any time via requestWithdrawal.
     *
     * @param token      ERC-20 token address on Base Sepolia
     * @param amount     Amount to deposit (token smallest unit, must be > 0)
     * @param strategyId Zama fhEVM strategy ID to link this deposit to (0 = none)
     */
    function deposit(
        address token,
        uint256 amount,
        uint256 strategyId
    ) external nonReentrant {
        require(token != address(0), "BaseVault: zero token address");
        require(amount > 0, "BaseVault: amount must be > 0");

        // ── Security fix (SECURITY.md finding 1.1): fee-on-transfer tokens ───────
        // Measure the actual tokens received rather than trusting `amount`.
        // For standard ERC-20 tokens `received == amount`; for tokens with a
        // transfer fee `received < amount`. Using `received` ensures the vault's
        // internal accounting never exceeds its real token balance.
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = IERC20(token).balanceOf(address(this)) - balanceBefore;
        require(received > 0, "BaseVault: received zero tokens");

        _available[msg.sender][token] += received;

        // Auto-link strategy if provided and not yet linked
        if (strategyId != 0 && _linkedStrategy[msg.sender] == 0) {
            _linkedStrategy[msg.sender] = strategyId;
            emit StrategyLinked(msg.sender, strategyId);
        }

        // Emit `received` (not `amount`) so downstream systems know the exact credit
        emit DepositCreated(msg.sender, token, received, strategyId);
    }

    // ── Strategy Linking ──────────────────────────────────────────────────────

    /**
     * @notice Link this account to a Zama fhEVM strategy ID.
     *
     * @dev The strategyId is opaque to BaseVault. It must correspond to
     *      a valid strategy in ConfidentialStrategyAgent on Zama fhEVM.
     *
     *      The relayer uses this link to know which strategy to shield into
     *      when processing a DepositCreated event.
     *
     *      Calling this again replaces the previous link.
     *
     * @param strategyId Zama fhEVM strategy ID (returned from createStrategy())
     */
    function linkStrategy(uint256 strategyId) external {
        _linkedStrategy[msg.sender] = strategyId;
        emit StrategyLinked(msg.sender, strategyId);
    }

    // ── Withdrawal ────────────────────────────────────────────────────────────

    /**
     * @notice Request withdrawal of `amount` tokens from the vault.
     *
     * @dev Moves `amount` from _available to _pending.
     *
     *      The WithdrawalRequested event signals the off-chain relayer to:
     *       1. Call ConfidentialToken.requestUnshield() on Zama fhEVM.
     *       2. Wait for the Zama Gateway callback (Unshielded event).
     *       3. Call relayerCompleteWithdrawal() on this contract.
     *
     *      If the relayer does not respond, the user can call
     *      cancelPendingWithdrawal() to reclaim their funds.
     *
     *      NOTE: Until the bridge is deployed, users should call
     *      cancelPendingWithdrawal() immediately to reclaim funds.
     *
     * @param token  ERC-20 token address
     * @param amount Amount to withdraw
     */
    function requestWithdrawal(
        address token,
        uint256 amount
    ) external nonReentrant {
        require(token != address(0), "BaseVault: zero token address");
        require(amount > 0, "BaseVault: amount must be > 0");
        require(
            _available[msg.sender][token] >= amount,
            "BaseVault: insufficient available balance"
        );

        _available[msg.sender][token] -= amount;
        _pending[msg.sender][token] += amount;

        emit WithdrawalRequested(msg.sender, token, amount);
    }

    /**
     * @notice Complete a pending withdrawal (relayer only).
     *
     * @dev Called by the relayer after confirming that the corresponding
     *      Zama fhEVM unshield has been processed and the ERC-20 has been
     *      locked on the Zama side (or burned/accounted for).
     *
     *      TODO: In production this would be called by the bridge contract
     *      automatically after the cross-chain message is verified.
     *
     * @param user   The user who requested withdrawal
     * @param token  ERC-20 token address
     * @param amount Amount to release
     */
    function relayerCompleteWithdrawal(
        address user,
        address token,
        uint256 amount
    ) external onlyRelayer nonReentrant {
        require(user != address(0), "BaseVault: zero user");
        require(
            _pending[user][token] >= amount,
            "BaseVault: insufficient pending balance"
        );

        _pending[user][token] -= amount;
        IERC20(token).safeTransfer(user, amount);

        emit WithdrawalCompleted(user, token, amount);
    }

    /**
     * @notice Cancel a pending withdrawal and return funds to available balance.
     *
     * @dev Use this if the relayer does not respond within a reasonable time,
     *      or if the bridge is not yet deployed and you need to recover funds.
     *
     *      Once the production bridge is deployed, this function should only
     *      be callable after a timeout (e.g. 24 hours) to prevent abuse.
     *      That timeout logic is left as a TODO.
     *
     * @param token  ERC-20 token address
     * @param amount Amount to cancel
     */
    function cancelPendingWithdrawal(
        address token,
        uint256 amount
    ) external nonReentrant {
        require(
            _pending[msg.sender][token] >= amount,
            "BaseVault: no pending withdrawal to cancel"
        );

        _pending[msg.sender][token] -= amount;
        _available[msg.sender][token] += amount;

        emit WithdrawalCancelled(msg.sender, token, amount);
    }

    /**
     * @notice Emergency withdrawal of ALL available balance for a token.
     *
     * @dev ⚠️  TESTNET / DEVELOPMENT SAFETY VALVE ONLY.
     *      This bypasses the relayer and transfers directly to msg.sender.
     *      It should be removed or timelocked before mainnet deployment.
     *
     *      Useful during development when the bridge is not yet deployed
     *      and a user needs to recover their funds without waiting for a relayer.
     *
     * @param token ERC-20 token address to withdraw
     */
    function emergencyWithdraw(address token) external nonReentrant {
        uint256 available = _available[msg.sender][token];
        require(available > 0, "BaseVault: nothing to withdraw");

        _available[msg.sender][token] = 0;
        IERC20(token).safeTransfer(msg.sender, available);

        emit WithdrawalCompleted(msg.sender, token, available);
    }

    // ── View Functions ────────────────────────────────────────────────────────

    /**
     * @notice Returns the available (not pending withdrawal) balance.
     */
    function getAvailableBalance(
        address user,
        address token
    ) external view returns (uint256) {
        return _available[user][token];
    }

    /**
     * @notice Returns the balance locked in pending withdrawal.
     */
    function getPendingWithdrawal(
        address user,
        address token
    ) external view returns (uint256) {
        return _pending[user][token];
    }

    /**
     * @notice Returns the Zama fhEVM strategy ID linked to this user.
     *         0 = no strategy linked.
     */
    function getLinkedStrategy(address user) external view returns (uint256) {
        return _linkedStrategy[user];
    }

    /**
     * @notice Returns the total vault balance for a given token
     *         (available + pending across all users).
     *
     * @dev    This is the actual ERC-20 balance held by the contract.
     *         It should always equal the sum of all _available + _pending values.
     */
    function vaultBalance(address token) external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }
}

contracts/ConfidentialToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title  ConfidentialToken
 * @notice Shield/unshield wrapper that gives a public ERC-20 an FHE-encrypted
 *         balance layer using Zama fhEVM v0.6 (https://docs.zama.ai/fhevm).
 *
 * Deployment requirements
 * ───────────────────────
 * Must be deployed on a network running Zama's fhEVM precompiles:
 *   - Ethereum Sepolia (Zama deployment, chainId 11155111)
 *   - Zama Devnet (chainId 9000)
 *
 * This contract inherits SepoliaZamaFHEVMConfig + SepoliaZamaGatewayConfig which
 * wire the pre-deployed system contract addresses in the constructor.
 *
 * Privacy model
 * ─────────────
 * - shield(uint64 amount)      : deposit amount is PUBLIC (comes from public ERC-20)
 * - transfer(…)                : amount is ENCRYPTED via fhevmjs before the call
 * - requestUnshield(…)         : amount is ENCRYPTED; Gateway decrypts async → callback
 *
 * The encrypted balance for each address is a euint64 handle.
 * Observers see only addresses and that a transfer occurred — not amounts.
 * To read one's own balance, call encryptedBalanceOf() and pass the returned handle
 * to fhevmjs.instance.reencrypt() with an EIP-712 signed keypair.
 */

import {TFHE, euint64, einput, ebool} from "fhevm/lib/TFHE.sol";
import {SepoliaZamaFHEVMConfig} from "fhevm/config/ZamaFHEVMConfig.sol";
import {SepoliaZamaGatewayConfig} from "fhevm/config/ZamaGatewayConfig.sol";
import {GatewayCaller} from "fhevm/gateway/GatewayCaller.sol";
import {Gateway} from "fhevm/gateway/lib/Gateway.sol";
import {IERC20, SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract ConfidentialToken is
    SepoliaZamaFHEVMConfig,
    SepoliaZamaGatewayConfig,
    GatewayCaller,
    Ownable,
    ReentrancyGuard
{
    using SafeERC20 for IERC20;

    // ── Immutable state ────────────────────────────────────────────────────────

    IERC20 public immutable underlying;
    string public name;
    string public symbol;

    // ── Encrypted state ────────────────────────────────────────────────────────

    /**
     * @dev euint64 handle → ciphertext maintained by Zama fhEVM nodes.
     *      The handle is public; only ACL-authorised addresses can re-encrypt
     *      it into plaintext (using fhevmjs.reencrypt).
     */
    mapping(address => euint64) private _encryptedBalances;

    /// @dev Running sum of all shielded tokens (encrypted).
    euint64 private _encryptedTotalShielded;

    // ── Pending unshields ──────────────────────────────────────────────────────

    /**
     * @dev Fields added for Gateway timeout recovery (SECURITY fix):
     *      `amount`       – the encrypted amount deducted from sender's balance.
     *                       Stored so it can be returned if the Gateway never fires.
     *      `maxTimestamp` – the deadline passed to Gateway.requestDecryption().
     *                       After this timestamp the sender may call recoverExpiredUnshield().
     */
    struct PendingUnshield {
        address sender;
        address recipient;
        euint64 amount;        // for recovery: re-credit sender if Gateway times out
        uint256 maxTimestamp;  // for recovery: eligibility check
    }
    mapping(uint256 => PendingUnshield) public pendingUnshields;

    // ── Events ─────────────────────────────────────────────────────────────────

    /// @notice Deposited `amount` tokens (plaintext – shield step is not private).
    event Shielded(address indexed account, uint64 amount);

    /// @notice Withdrawal requested. Amount is unknown until Gateway callback.
    event UnshieldRequested(
        address indexed sender,
        address indexed recipient,
        uint256 indexed requestId
    );

    /// @notice Withdrawal complete (amount revealed here because it left the pool).
    event Unshielded(
        address indexed sender,
        address indexed recipient,
        uint64 amount
    );

    /**
     * @notice Emitted when an expired unshield request is recovered.
     * @dev    This restores the encrypted balance to the original sender.
     *         No amount is logged (balance remains encrypted).
     */
    event UnshieldRecovered(address indexed sender, uint256 indexed requestId);

    /**
     * @notice Confidential transfer occurred.
     * @dev    No `amount` field. Amount is permanently encrypted.
     */
    event Transfer(address indexed from, address indexed to);

    // ── Constructor ────────────────────────────────────────────────────────────

    constructor(
        address _underlying,
        string memory _name,
        string memory _symbol,
        address _initialOwner
    ) Ownable(_initialOwner) {
        require(_underlying != address(0), "ConfidentialToken: zero underlying");
        underlying = IERC20(_underlying);
        name = _name;
        symbol = _symbol;
    }

    // ── Shield ─────────────────────────────────────────────────────────────────

    /**
     * @notice Deposit `amount` of the underlying ERC-20 into the confidential pool.
     *
     * @dev The deposited `amount` is plaintext — it is visible on-chain because
     *      it comes from the user's public ERC-20 wallet.  Privacy begins from
     *      the first `transfer()` call after shielding.
     *
     *      Caller must call underlying.approve(address(this), amount) first.
     *
     * @param amount  Number of tokens (uint64, in the underlying token's smallest unit).
     */
    function shield(uint64 amount) external nonReentrant {
        require(amount > 0, "ConfidentialToken: amount must be > 0");

        underlying.safeTransferFrom(msg.sender, address(this), amount);

        // trivialEncrypt wraps a plaintext uint64 into an encrypted euint64.
        // The resulting ciphertext is trivial (known to everyone) but allows
        // the handle to participate in further FHE arithmetic.
        if (!TFHE.isInitialized(_encryptedBalances[msg.sender])) {
            _encryptedBalances[msg.sender] = TFHE.asEuint64(uint256(amount));
        } else {
            _encryptedBalances[msg.sender] = TFHE.add(
                _encryptedBalances[msg.sender],
                TFHE.asEuint64(uint256(amount))
            );
        }

        TFHE.allow(_encryptedBalances[msg.sender], address(this));
        TFHE.allow(_encryptedBalances[msg.sender], msg.sender);

        if (!TFHE.isInitialized(_encryptedTotalShielded)) {
            _encryptedTotalShielded = TFHE.asEuint64(uint256(amount));
        } else {
            _encryptedTotalShielded = TFHE.add(
                _encryptedTotalShielded,
                TFHE.asEuint64(uint256(amount))
            );
        }
        TFHE.allow(_encryptedTotalShielded, address(this));
        TFHE.allow(_encryptedTotalShielded, owner());

        emit Shielded(msg.sender, amount);
    }

    // ── Confidential Transfer ──────────────────────────────────────────────────

    /**
     * @notice Transfer an encrypted amount within the pool.
     *
     * @dev The caller must produce `encryptedAmount` and `inputProof` using
     *      fhevmjs on the client:
     *
     *        const input = instance.createEncryptedInput(contractAddress, signerAddress);
     *        input.add64(amountInSmallestUnit);
     *        const { handles, inputProof } = await input.encrypt();
     *        // handles[0] → encryptedAmount (bytes32)
     *        // inputProof  → inputProof      (bytes)
     *
     *      TFHE.le checks balance ≥ amount without revealing either value.
     *      TFHE.select conditionally applies the debit/credit (never reverts on
     *      insufficient balance, because a revert would leak information).
     *
     * @param to              Recipient (must be a non-zero address != sender).
     * @param encryptedAmount fhevmjs-produced ciphertext handle (bytes32 / einput).
     * @param inputProof      fhevmjs-produced input proof.
     */
    function transfer(
        address to,
        einput encryptedAmount,
        bytes calldata inputProof
    ) external nonReentrant returns (bool) {
        require(to != address(0), "ConfidentialToken: transfer to zero address");
        require(to != msg.sender, "ConfidentialToken: self-transfer not allowed");
        require(
            TFHE.isInitialized(_encryptedBalances[msg.sender]),
            "ConfidentialToken: sender has no shielded balance"
        );

        euint64 amount = TFHE.asEuint64(encryptedAmount, inputProof);

        // Homomorphic balance check: silently transfer 0 if insufficient.
        ebool canTransfer = TFHE.le(amount, _encryptedBalances[msg.sender]);
        euint64 actualAmount = TFHE.select(canTransfer, amount, TFHE.asEuint64(0));

        _encryptedBalances[msg.sender] = TFHE.sub(
            _encryptedBalances[msg.sender],
            actualAmount
        );
        TFHE.allow(_encryptedBalances[msg.sender], address(this));
        TFHE.allow(_encryptedBalances[msg.sender], msg.sender);

        if (!TFHE.isInitialized(_encryptedBalances[to])) {
            _encryptedBalances[to] = actualAmount;
        } else {
            _encryptedBalances[to] = TFHE.add(_encryptedBalances[to], actualAmount);
        }
        TFHE.allow(_encryptedBalances[to], address(this));
        TFHE.allow(_encryptedBalances[to], to);

        emit Transfer(msg.sender, to);
        return true;
    }

    // ── Unshield (async via Gateway) ───────────────────────────────────────────

    /**
     * @notice Request withdrawal of an encrypted amount back to a public address.
     *
     * @dev Two-step process:
     *       1. This function deducts the encrypted amount and asks the Gateway
     *          to decrypt it.
     *       2. The Gateway calls `callbackUnshield` with the plain uint64.
     *          The ERC-20 transfer happens there.
     *
     *      On Zama Devnet the Gateway callback fires within ~1-2 blocks.
     *
     *      Caller must produce encryptedAmount + inputProof with fhevmjs.
     */
    function requestUnshield(
        einput encryptedAmount,
        bytes calldata inputProof,
        address recipient
    ) external nonReentrant {
        require(recipient != address(0), "ConfidentialToken: zero recipient");
        require(
            TFHE.isInitialized(_encryptedBalances[msg.sender]),
            "ConfidentialToken: sender has no shielded balance"
        );

        euint64 amount = TFHE.asEuint64(encryptedAmount, inputProof);

        ebool canUnshield = TFHE.le(amount, _encryptedBalances[msg.sender]);
        euint64 actualAmount = TFHE.select(canUnshield, amount, TFHE.asEuint64(0));

        // Deduct before the async callback to prevent re-entrancy / double-spend.
        _encryptedBalances[msg.sender] = TFHE.sub(
            _encryptedBalances[msg.sender],
            actualAmount
        );
        TFHE.allow(_encryptedBalances[msg.sender], address(this));
        TFHE.allow(_encryptedBalances[msg.sender], msg.sender);

        _encryptedTotalShielded = TFHE.sub(_encryptedTotalShielded, actualAmount);
        TFHE.allow(_encryptedTotalShielded, address(this));
        TFHE.allow(_encryptedTotalShielded, owner());

        // Grant persistent ACL so the contract can access `actualAmount` in recovery,
        // and grant sender access so they can re-encrypt it if needed.
        TFHE.allow(actualAmount, address(this));
        TFHE.allow(actualAmount, msg.sender);

        // Grant Gateway transient ACL to decrypt `actualAmount` for the callback.
        TFHE.allowTransient(actualAmount, Gateway.gatewayContractAddress());

        uint256[] memory handles = new uint256[](1);
        handles[0] = Gateway.toUint256(actualAmount);

        // Store maxTimestamp so the sender can recover if the Gateway never calls back.
        uint256 maxTs = block.timestamp + 1 hours;

        uint256 requestId = Gateway.requestDecryption(
            handles,
            this.callbackUnshield.selector,
            0,
            maxTs,
            false // passSignaturesToCaller
        );

        pendingUnshields[requestId] = PendingUnshield({
            sender:       msg.sender,
            recipient:    recipient,
            amount:       actualAmount,
            maxTimestamp: maxTs
        });

        emit UnshieldRequested(msg.sender, recipient, requestId);
    }

    /**
     * @notice Gateway callback – called after decrypting the unshield amount.
     * @dev    Only the Gateway contract can call this (enforced by `onlyGateway`).
     * @param  requestId        ID returned by Gateway.requestDecryption.
     * @param  decryptedAmount  Plain uint64 produced by the Gateway.
     */
    function callbackUnshield(
        uint256 requestId,
        uint64 decryptedAmount
    ) external onlyGateway {
        PendingUnshield memory pending = pendingUnshields[requestId];
        require(pending.recipient != address(0), "ConfidentialToken: unknown requestId");

        delete pendingUnshields[requestId];

        if (decryptedAmount > 0) {
            underlying.safeTransfer(pending.recipient, decryptedAmount);
        }

        emit Unshielded(pending.sender, pending.recipient, decryptedAmount);
    }

    // ── Unshield Recovery ──────────────────────────────────────────────────────

    /**
     * @notice Recover a shielded balance from an unshield request that the
     *         Zama Gateway never resolved (Gateway timeout / outage).
     *
     * @dev    Security fix for SECURITY.md finding 2.1:
     *         "Gateway timeout: Unshielded Funds May Be Permanently Lost"
     *
     *         The sender's balance was already deducted when requestUnshield() was
     *         called (to prevent double-spend). If the Gateway never fires
     *         callbackUnshield() within the maxTimestamp window, the encrypted
     *         amount is re-credited to the sender here.
     *
     *         Only callable by the ORIGINAL SENDER after maxTimestamp has passed.
     *         Anyone else calling will revert.
     *
     *         Note: if callbackUnshield() already fired (succeeded), the
     *         pendingUnshields entry is deleted and this function reverts with
     *         "unknown requestId" — preventing double-recovery.
     *
     * @param requestId  The request ID returned by requestUnshield().
     */
    function recoverExpiredUnshield(uint256 requestId) external nonReentrant {
        PendingUnshield memory pending = pendingUnshields[requestId];
        require(
            pending.sender != address(0),
            "ConfidentialToken: unknown requestId"
        );
        require(
            msg.sender == pending.sender,
            "ConfidentialToken: not the original sender"
        );
        require(
            block.timestamp > pending.maxTimestamp,
            "ConfidentialToken: unshield request not yet expired"
        );

        // Delete first (checks-effects-interactions)
        delete pendingUnshields[requestId];

        // Re-add the encrypted amount to the sender's balance
        if (!TFHE.isInitialized(_encryptedBalances[pending.sender])) {
            _encryptedBalances[pending.sender] = pending.amount;
        } else {
            _encryptedBalances[pending.sender] = TFHE.add(
                _encryptedBalances[pending.sender],
                pending.amount
            );
        }
        TFHE.allow(_encryptedBalances[pending.sender], address(this));
        TFHE.allow(_encryptedBalances[pending.sender], pending.sender);

        // Restore the total shielded counter
        if (!TFHE.isInitialized(_encryptedTotalShielded)) {
            _encryptedTotalShielded = pending.amount;
        } else {
            _encryptedTotalShielded = TFHE.add(
                _encryptedTotalShielded,
                pending.amount
            );
        }
        TFHE.allow(_encryptedTotalShielded, address(this));
        TFHE.allow(_encryptedTotalShielded, owner());

        // No amount in the event – balance remains encrypted
        emit UnshieldRecovered(pending.sender, requestId);
    }

    // ── Read ───────────────────────────────────────────────────────────────────

    /**
     * @notice Returns the encrypted balance handle for `account`.
     *
     * @dev The returned uint256 is a ciphertext handle.  To get the plaintext
     *      balance, use fhevmjs.reencrypt() — see src/hooks/useTokenBalance.ts.
     */
    function encryptedBalanceOf(address account) external view returns (euint64) {
        return _encryptedBalances[account];
    }

    /// @notice Encrypted running total (only owner has ACL access).
    function encryptedTotalShielded() external view returns (euint64) {
        return _encryptedTotalShielded;
    }

    // ── Emergency ──────────────────────────────────────────────────────────────

    /// @notice Rescue accidentally-sent ERC-20 tokens (not the underlying).
    function rescueTokens(address token, uint256 amount) external onlyOwner {
        require(token != address(underlying), "ConfidentialToken: cannot rescue underlying");
        IERC20(token).safeTransfer(owner(), amount);
    }
}

